const cmds = [
  ["git rev-parse --show-toplevel", "root"],
  ["git rev-parse --abbrev-ref --symbolic-full-name @{upstream}", "upstream"],
  ["git branch --list main", "main"],
  ["git status --short", "status"],
  ["rg --files -g 'AGENTS.md' -g '!**/.git/**'", "agents"]
];
const results = await Promise.all(cmds.map(async ([cmd, label]) => {
  const r = await tools.exec_command({cmd, workdir:"/home/mark/kramtime/llm-skillbook-review-team-worktree", yield_time_ms:10000, max_output_tokens:3000});
